import{_ as i,o as n,c as e,a2 as s}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Tesis Inti Anti-Predasionisme","description":"","frontmatter":{},"headers":[],"relativePath":"id/04-反掠夺主义核心论纲.md","filePath":"id/04-反掠夺主义核心论纲.md"}'),t={name:"id/04-反掠夺主义核心论纲.md"};function r(d,a,u,k,m,l){return n(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="tesis-inti-anti-predasionisme" tabindex="-1">Tesis Inti Anti-Predasionisme <a class="header-anchor" href="#tesis-inti-anti-predasionisme" aria-label="Permalink to &quot;Tesis Inti Anti-Predasionisme&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>04</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Anti-Predasionisme, Kritik Predasi, Alternatif Simbiosis, Batas Etika, Revolusi Sistem</td></tr></tbody></table><h2 id="i-definisi-dan-manifestasi-predasionisme" tabindex="-1">I. Definisi dan Manifestasi Predasionisme <a class="header-anchor" href="#i-definisi-dan-manifestasi-predasionisme" aria-label="Permalink to &quot;I. Definisi dan Manifestasi Predasionisme&quot;">​</a></h2><p>Predasionisme merujuk pada pandangan kosmik dan sistem kultivasi yang menggunakan perampasan gratis, pemangsaan, atau eksploitasi asal, energi, keberuntungan, dan sumber daya dari makhluk lain atau bidang lain sebagai sarana utama, dengan tujuan mencapai evolusi diri sendiri atau kelompok sendiri. Predasionisme bukanlah metode kultivasi tertentu, melainkan posisi fundamental yang meresapi filosofi kultivasi, institusi sosial, dan hubungan peradaban.</p><p>Dalam sejarah Heng Yuan Zhou, predasionisme telah bermanifestasi dalam bentuk-bentuk utama berikut:</p><table tabindex="0"><thead><tr><th>Bentuk</th><th>Manifestasi</th><th>Kerusakan</th></tr></thead><tbody><tr><td>Predasi Energi</td><td>Memangsa langsung energi kultivasi atau asal makhluk lain</td><td>Menyebabkan kematian atau hancurnya kultivasi yang dipredasi, siklus energi kosmik terputus</td></tr><tr><td>Predasi Keberuntungan</td><td>Mencuri keberuntungan individu atau ras lain melalui seni rahasia</td><td>Menyebabkan runtuhnya takdir yang dipredasi, kemunduran ras</td></tr><tr><td>Monopoli Metode</td><td>Beberapa sekte memonopoli metode kultivasi, menukar otorisasi dengan kesetiaan dan sumber daya</td><td>Menyebabkan stratifikasi kaku, makhluk lapisan bawah kehilangan jalur evolusi</td></tr><tr><td>Kolonialisme Bidang</td><td>Bidang tinggi menaklukkan bidang rendah, memangsa sumber daya dan populasinya</td><td>Menyebabkan kerusakan membran bidang, runtuhnya ekologi bidang</td></tr><tr><td>Perbudakan Spiritual</td><td>Mengubah makhluk lain menjadi alat kultivasi melalui kontrol jiwa</td><td>Merampas kehendak bebas yang diperbudak, melanggar martabat kehidupan</td></tr><tr><td>Penipisan Sumber Daya</td><td>Mengeksploitasi sumber daya planet atau bidang tanpa batas</td><td>Menyebabkan kepunahan ekologis, mempercepat peningkatan entropi kosmik</td></tr></tbody></table><h2 id="ii-kesalahan-fundamental-predasionisme" tabindex="-1">II. Kesalahan Fundamental Predasionisme <a class="header-anchor" href="#ii-kesalahan-fundamental-predasionisme" aria-label="Permalink to &quot;II. Kesalahan Fundamental Predasionisme&quot;">​</a></h2><p>Anti-predasionisme menganggap bahwa predasionisme pada dasarnya mengandung tiga kesalahan:</p><h3 id="_2-1-kesalahan-pandangan-kosmik-menganggap-kosmos-sebagai-ladang-berburu-terbatas" tabindex="-1">2.1 Kesalahan Pandangan Kosmik: Menganggap kosmos sebagai ladang berburu terbatas <a class="header-anchor" href="#_2-1-kesalahan-pandangan-kosmik-menganggap-kosmos-sebagai-ladang-berburu-terbatas" aria-label="Permalink to &quot;2.1 Kesalahan Pandangan Kosmik: Menganggap kosmos sebagai ladang berburu terbatas&quot;">​</a></h3><p>Pandangan kosmik predasionisme menganggap kosmos sebagai ladang berburu dengan sumber daya terbatas, percaya bahwa evolusi pasti merupakan permainan jumlah nol, dan kemajuan yang kuat harus mengorbankan yang lemah. Pandangan kosmik ini mengabaikan &quot;kemampuan berevolusi&quot; dari kosmos itu sendiri — kosmos bukanlah wadah sumber daya statis, melainkan makhluk hidup yang dapat mencapai kenaikan dimensi global melalui jaringan simbiosis yang teratur. Ketika predator memangsa yang lemah, mereka tidak hanya mengonsumsi energi yang lemah, tetapi juga potensi evolusi dari seluruh kosmos.</p><h3 id="_2-2-kesalahan-etika-menempatkan-hak-evolusi-yang-kuat-di-atas-hak-hidup-yang-lemah" tabindex="-1">2.2 Kesalahan Etika: Menempatkan hak evolusi yang kuat di atas hak hidup yang lemah <a class="header-anchor" href="#_2-2-kesalahan-etika-menempatkan-hak-evolusi-yang-kuat-di-atas-hak-hidup-yang-lemah" aria-label="Permalink to &quot;2.2 Kesalahan Etika: Menempatkan hak evolusi yang kuat di atas hak hidup yang lemah&quot;">​</a></h3><p>Predasionisme menerima &quot;hukum yang kuat memangsa yang lemah&quot; sebagai hukum alam, percaya bahwa yang kuat memiliki hak dan bahkan kewajiban untuk memangsa yang lemah. Pandangan etika ini membingungkan seleksi alam dengan pilihan moral. Di alam, hukum yang kuat memangsa yang lemah adalah hukum ekologis yang tidak disadari; tetapi dalam peradaban kultivasi yang sadar, yang kuat memiliki kemampuan untuk memilih, dan therefore harus memikul tanggung jawab dari pilihannya. Predasi yang menggunakan &quot;hukum langit&quot; sebagai alibi, pada dasarnya adalah yang kuat menyamarkan keserakahan mereka sendiri sebagai hukum kosmik.</p><h3 id="_2-3-kesalahan-efisiensi-percaya-bahwa-predasi-adalah-jalur-evolusi-tercepat" tabindex="-1">2.3 Kesalahan Efisiensi: Percaya bahwa predasi adalah jalur evolusi tercepat <a class="header-anchor" href="#_2-3-kesalahan-efisiensi-percaya-bahwa-predasi-adalah-jalur-evolusi-tercepat" aria-label="Permalink to &quot;2.3 Kesalahan Efisiensi: Percaya bahwa predasi adalah jalur evolusi tercepat&quot;">​</a></h3><p>Predasionisme mengklaim bahwa predasi adalah jalur evolusi tercepat dan paling efisien. Namun, dalam jangka panjang, evolusi predator memiliki &quot;langit-langit efisiensi&quot; yang serius: pertama, energi yang diperoleh melalui predasi sering kali membawa jejak kehendak pemilik asli, membutuhkan upaya besar untuk menyempurnakan dan memurnikan; kedua, perilaku predator memicu perlawanan dari yang dipredasi dan kelompok terkait mereka, meningkatkan biaya eksternal kultivasi; ketiga, ketergantungan jangka panjang pada predasi menyebabkan degenerasi kemampuan evolusi kultivator itu sendiri, yang memasuki stagnasi setelah kehilangan objek predasi; keempat, kultivator predator sering menghadapi hambatan &quot;asal tidak murni&quot; ketika menembus tingkat tertinggi, tidak mampu menyentuh asal kosmik yang sebenarnya.</p><h2 id="iii-proposisi-inti-anti-predasionisme" tabindex="-1">III. Proposisi Inti Anti-Predasionisme <a class="header-anchor" href="#iii-proposisi-inti-anti-predasionisme" aria-label="Permalink to &quot;III. Proposisi Inti Anti-Predasionisme&quot;">​</a></h2><p>Anti-predasionisme tidak sekadar menyangkal semua persaingan dan perbedaan, tetapi mengajukan proposisi inti berikut:</p><ol><li><strong>Evolusi bisa bukan jumlah nol</strong>: Melalui siklus simbiosis dan jaringan titik jangkar, evolusi Sepuluh Ribu Ras dapat menghasilkan efek sinergis, mencapai efisiensi evolusi global yang melampaui jumlah bagian-bagiannya.</li><li><strong>Persaingan harus kreatif bukan destruktif</strong>: Anti-predasionisme tidak menentang persaingan sehat, tetapi cara persaingan harus meningkatkan kemampuan kreatif diri sendiri, bukan kemampuan predator untuk melenyapkan lawan.</li><li><strong>Tanggung jawab yang kuat lebih besar daripada haknya</strong>: Semakin tinggi tingkat kultivator, semakin besar tanggung jawabnya terhadap jaringan simbiosis, bukan semakin besar hak predasinya. Kultivator tingkat lanjut memiliki kewajiban untuk membimbing kultivator pemula, menjaga stabilitas titik jangkar, dan melindungi keamanan peradaban.</li><li><strong>Sumber daya harus ditingkatkan melalui penciptaan bukan didistribusikan melalui predasi</strong>: Ide inti peradaban simbiosis adalah memperbesar kue, bukan membagi kue; melalui kemajuan teknologi dan penerapan hukum, terus menciptakan sumber daya kultivasi baru.</li><li><strong>Anti-predasionisme bukan egalitarianisme</strong>: Yang ditentang anti-predasionisme adalah predasi tanpa usaha, bukan perbedaan lebih banyak kerja lebih banyak imbalan. Peradaban simbiosis mengakui perbedaan hasil evolusi, tetapi bersikeras bahwa perbedaan harus berasal dari usaha dan kontribusi diri sendiri.</li></ol><h2 id="iv-jaminan-institusional-anti-predasionisme" tabindex="-1">IV. Jaminan Institusional Anti-Predasionisme <a class="header-anchor" href="#iv-jaminan-institusional-anti-predasionisme" aria-label="Permalink to &quot;IV. Jaminan Institusional Anti-Predasionisme&quot;">​</a></h2><p>Anti-predasionisme bukan hanya proposisi teoretis, tetapi memiliki serangkaian jaminan institusional:</p><ul><li><strong>Jaminan Hukum</strong>: Konstitusi simbiosis dan hukum anti-monopoli secara eksplisit melarang perilaku predator, Pengadilan Jangkar memiliki yurisdiksi atas kasus predasi</li><li><strong>Jaminan Mekanistik</strong>: Sistem kontrak berbasis produksi memastikan distribusi sumber daya didasarkan pada kontribusi bukan kekerasan, jaringan titik jangkar memantau aliran energi abnormal</li><li><strong>Jaminan Sistem</strong>: Tiga Ratus Sistem Kultivasi Asal semuanya didasarkan pada prinsip siklus simbiosis, tidak ada metode predator</li><li><strong>Jaminan Pendidikan</strong>: Sistem pendidikan simbiosis menjadikan etika anti-predasi sebagai mata pelajaran wajib, memberantas pemikiran predator dari akarnya</li><li><strong>Jaminan Pengawasan</strong>: Parlemen Republik Sepuluh Ribu Ras membentuk komisi anti-predasi, yang khusus mengawasi dan menyelidiki perilaku predator</li></ul><h2 id="v-kebijakan-terhadap-kekuatan-predator-yang-tersisa" tabindex="-1">V. Kebijakan terhadap Kekuatan Predator yang Tersisa <a class="header-anchor" href="#v-kebijakan-terhadap-kekuatan-predator-yang-tersisa" aria-label="Permalink to &quot;V. Kebijakan terhadap Kekuatan Predator yang Tersisa&quot;">​</a></h2><p>Untuk kekuatan predator yang tersisa yang masih ada di kosmos, peradaban simbiosis mengadopsi kebijakan gabungan &quot;isolasi, transformasi, sanksi&quot;: untuk predator yang belum menyebabkan kerusakan parah, dilakukan pendidikan etika dan transformasi sistem, membimbing mereka untuk bergabung dengan sistem simbiosis; untuk predator yang menolak transformasi dan terus merusak tatanan simbiosis, diterapkan isolasi bidang dan pembatasan kultivasi; untuk predator yang menyebabkan bencana parah, diterapkan sanksi sesuai hukum. Peradaban simbiosis tidak menganjurkan anti-predasi melalui predasi, dan semua sanksi harus melalui pengadilan yang adil dari Pengadilan Jangkar.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Anti-predasionisme adalah salah satu landasan teoretis dari Peradaban Simbiosis Jangkar. Ini bukan hanya kritik terhadap sistem predator era lama, tetapi juga konstruksi aktif dari kemungkinan evolusi simbiosis. Tujuan utama anti-predasionisme bukanlah melenyapkan yang kuat, melainkan membuat kekuatan yang kuat melayani evolusi bersama Sepuluh Ribu Ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Deklarasi Peradaban Simbiosis Jangkar)</li><li>03-共生文明宪章 (Konstitusi Peradaban Simbiosis)</li><li>19-修炼伦理与边界 (Etika dan Batas Kultivasi)</li></ul>',26)])])}const p=i(t,[["render",r]]);export{g as __pageData,p as default};
